package com.vityarthi.library;
import com.vityarthi.library.model.Reservation;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ReservationQueueTest{@Test void priorityThenTime(){Reservation a=new Reservation(1,1,1,1,LocalDateTime.of(2026,9,1,10,0),"WAITING"),b=new Reservation(2,1,2,3,LocalDateTime.of(2026,9,1,11,0),"WAITING"),c=new Reservation(3,1,3,3,LocalDateTime.of(2026,9,1,9,0),"WAITING");PriorityQueue<Reservation>q=new PriorityQueue<>(Comparator.comparingInt(Reservation::getPriority).reversed().thenComparing(Reservation::getReservedAt).thenComparingLong(Reservation::getId));q.add(a);q.add(b);q.add(c);assertEquals(3,q.poll().getPriority());assertEquals(3,q.poll().getId());assertEquals(1,q.poll().getId());}}